typedef unsigned long size_t; typedef unsigned long long uint64_t; typedef unsigned uint32_t;
extern void *calloc(size_t,size_t);extern void free(void*);extern int printf(const char*,...);extern int puts(const char*);
int run(int N,int k){int E=0;uint32_t lo[22]={0};for(int j=0;j<N;j++)for(int i=0;i<j;i++)if((j-i)%k==1){lo[j]|=1u<<i;E++;}int W=E+1;size_t Z=((size_t)1<<N)*W;uint64_t*d=calloc(Z,8);if(!d)return 2;d[0]=1;for(unsigned s=1;s<(1u<<N);s++)for(unsigned t=s;t;t&=t-1){int j=__builtin_ctz(t);unsigned prev=s^(1u<<j);int shift=__builtin_popcount(lo[j]&prev);for(int e=shift;e<=E;e++)d[(size_t)s*W+e]+=d[(size_t)prev*W+e-shift];}uint64_t*a=&d[(((size_t)1<<N)-1)*W],sum=0;int down=0,bad=0;for(int e=0;e<=E;e++){sum+=a[e];if(e){if(a[e]<a[e-1])down=1;if(down&&a[e]>a[e-1])bad=1;}}printf("N %d type_A_n %d k %d degree %d sum %llu unimodal %d\ncoefficients ",N,N-1,k,E,(unsigned long long)sum,!bad);for(int e=0;e<=E;e++)printf("%llu,",(unsigned long long)a[e]);puts("");free(d);return bad;}
